import java.util.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        List<Long>[] data = new ArrayList[11];
        for (int i = 0; i <= 10; i++) {
            data[i] = new ArrayList<>();
        }
        long[] total = new long[11];
        final long MOD1 = 998244353;
        final long MOD2 = 1000000007;

        long count = 0;
        long tmp_count = 0;
        long res = 0;

        Function<Long, Long> mod_func = (Long x) -> {
            long resMod = x % MOD1;
            if (resMod < 0) {
                resMod += MOD1;
            }
            return resMod;
        };

        class Build1 {
            void run(int level, long val) {
                if (val > n) return;
                if (level > 6) return;
                count++;
                long v = mod_func.apply(count - val);
                data[level].add(v);
                total[level] += v;
                for (int d = 0; d <= 9; d++) {
                    run(level + 1, val * 10 + d);
                }
            }
        }

        class Build2 {
            void run(int level, long val) {
                if (val > n) return;
                if (level >= 1) {
                    if (val * 10 * n > n && val * n + n -1 <= n) {
                        for (int i = 0; i <= 6; i++) {
                            long v = mod_func.apply(count - val);
                            List<Long> vec = data[i];
                            int pos = lowerBound(vec, MOD1 - v);
                            long size = vec.size();
                            res = (res + v * size + total[i] - MOD2 * (size - pos)) % MOD2;
                        }
                        count += tmp_count;
                        return;
                    }
                    count++;
                    long v = mod_func.apply(count - val);
                    res = (res + v) % MOD2;
                }

                for (int d = (level == 0 ? 1 : 0); d <= 9; d++) {
                    run(level + 1, val * 10 + d);
                }
            }
        }

        // Build1
        new Build1().run(0, 0);
        tmp_count = count;
        count = 0;
        // sort data
        for (int i = 0; i <= 6; i++) {
            Collections.sort(data[i]);
        }
        // Build2
        new Build2().run(0, 0);

        System.out.println(res);
        sc.close();
    }

    private static int lowerBound(List<Long> list, long key) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
